    oneplus=[0]*M; oneminus=[0]*M
    oneplus[0]=1; oneplus[1%M]=(oneplus[1%M]+1)%MOD
    oneminus[0]=1; oneminus[1%M]=(oneminus[1%M]-1)%MOD
    cache={}
    w=[0]*size
    for s,v in enumerate(f):
        p=(N+v)//2
        if p not in cache:
            x=power(oneplus,p,M)
            y=power(oneminus,N-p,M)
