from typing import List

class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        by_right = [[] for _ in range(n + 1)]
        for i, (a, b) in enumerate(conflictingPairs):
            x, y = sorted((a, b))
            by_right[y].append((x, i))

        heap = []
        gain = [0] * len(conflictingPairs)
        base = 0

        for r in range(1, n + 1):
            for x, i in by_right[r]:
                heapq.heappush(heap, (-x, i))

            if not heap:
                base += r
                continue

            top = heapq.heappop(heap)
            largest = -top[0]
            second_largest = -heap[0][0] if heap else 0
            heapq.heappush(heap, top)

            base += r - largest
            if largest > second_largest:
                gain[top[1]] += largest - second_largest

        return base + max(gain)

