class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        MOD = 10**9 + 7
        n = len(s)
        steps = [0] * (n + 1)
        for x in range(2, n + 1):
            steps[x] = 1 + steps[x.bit_count()]
        allowed = [w for w in range(1, n + 1) if steps[w] <= k - 1]
        comb = [[0] * (n + 1) for _ in range(n + 1)]
        comb[0][0] = 1
        for i in range(1, n + 1):
            comb[i][0] = comb[i][i] = 1
            for j in range(1, i):
                comb[i][j] = (comb[i - 1][j - 1] + comb[i - 1][j]) % MOD
        ans = 0
        ones = 0
        for i, bit in enumerate(s):
            if bit == '1':
                rem = n - i - 1
                for w in allowed:
                    need = w - ones
                    if 0 <= need <= rem:
                        ans += comb[rem][need]
                ones += 1
        return ans % MOD

